export {
  BrokerError,
  BudgetError,
  IdentityError,
  LicenseError,
  OriginRejectedError,
  PaymentRequiredError,
  RailError,
  isBrokerError,
} from './errors.js';

export { micros, formatMicros, addMicros, MICRO_PER_UNIT } from './amounts.js';
export type { Micros, Price, Quote } from './amounts.js';

export * from './types.js';
export { systemClock, frozenClock, makeFetchId, makeSettlementRef } from './time.js';
export type { Clock } from './time.js';
export { b64url, fromB64url, headerRecordToSortedEntries } from './util.js';

import type { Price, Quote } from './amounts.js';

/** A string constrained to a valid absolute URL at construction. */
export type UrlString = string & { readonly __brand: 'UrlString' };

export function url(value: string): UrlString {
  try {
    return new URL(value) as unknown as UrlString;
  } catch (cause) {
    throw new TypeError(`url(): invalid absolute URL: ${value}`, { cause });
  }
}

export type HeaderRecord = Record<string, string>;

/**
 * The three distinct failure classes. Today's agents collapse all of these
 * into a generic fetch failure; the broker reports each separately so the
 * cost decision is visible.
 */
export type FailureClass = 'blocked' | 'payment-required' | 'token-rejected';

export type FetchStatus = 'fulfilled' | 'denied' | 'error';

export interface FetchParams {
  url: UrlString;
  headers?: HeaderRecord;
  /** Optional tenant/subject for multi-tenant accounting. */
  tenantId?: string;
  /** Extra budget context from the caller, merged under broker policy. */
  budgetOverride?: { perCallCeilingMicros?: number; lineItemCeilingMicros?: number };
}

export type RslClauseType =
  | 'attribution'
  | 'no-store'
  | 'no-derivative-works'
  | 'no-commercial-use'
  | 'pay-per-inference'
  | 'redistribution'
  | (string & {});

export type RslClauseValue = 'required' | 'permitted' | 'forbidden' | number;

export interface RslClause {
  type: string;
  value: RslClauseValue;
  params: Record<string, string | number>;
}

/** A parsed Rights Statement Language (RSL) document. */
export interface License {
  draft: string;
  id: string;
  title?: string;
  publishedAt?: string;
  clauses: RslClause[];
  rawSource: string;
}

/**
 * Obligations the broker derives from a license and enforces/surfaces for
 * this particular fetch. Surfaced in the outcome so the caller can comply.
 */
export interface LicenseObligation {
  clause: string;
  kind: 'notice' | 'store-prohibited' | 'inference-budget' | 'forbidden' | 'permitted';
  instruction: string;
  applied?: string;
}

export interface IdentityPresentation {
  keyId: string;
  algorithm: 'ed25519';
  signedHeaders: string[];
  timestamp: string;
  /** Opaque PACT-style attestation token where the origin accepts one. */
  pactToken?: string;
}

export interface FetchOutcome {
  fetchId: string;
  status: FetchStatus;
  /** Present iff status !== 'fulfilled'. The three distinct failure classes. */
  failureClass?: FailureClass;
  reason: string;
  origin?: { url: string; httpStatus?: number };
  content?: { body: string; contentType: string; storeable: boolean; attributionNotice?: string };
  license?: License;
  obligations?: LicenseObligation[];
  price?: Price;
  quote?: Quote;
  rail?: string;
  settlementRef?: string;
  identity?: IdentityPresentation;
  tenantId?: string;
  timestamps: { startedAt: string; completedAt: string };
  error?: { code: string; message: string };
}

/** A raw ledger row — the audit surface. */
export interface LedgerEntry {
  seq: number;
  fetchId: string;
  tenantId: string;
  url: string;
  status: FetchStatus;
  failureClass?: FailureClass;
  httpStatus?: number;
  priceMicros?: number;
  currency?: string;
  rail?: string;
  licenseId?: string;
  keyId?: string;
  settlementRef?: string;
  startedAt: string;
  completedAt: string;
  recordedAt: string;
}

/**
 * A payment rail: one interface, pluggable backends.
 * Backends: x402 facilitator, Cloudflare Pay Per Crawl, self-hosted 402.
 * The interface is stable; backend field names are not (draft-caveat discipline).
 */
export interface PaymentRequest {
  url: UrlString;
  method: string;
  headers: HeaderRecord;
  contentType?: string;
}

export interface RailAuthorization {
  /** Headers the origin expects on the settled request (e.g. X-PAYMENT). */
  settlementHeaders: HeaderRecord;
  scheme: string;
  payload: string;
}

export interface RailSettlement {
  rail: string;
  settlementRef: string;
  amountMicros: number;
  currency: string;
  settledAt: string;
}

export interface PaymentRail {
  readonly id: string;
  quote(req: PaymentRequest): Promise<Quote>;
  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization>;
  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement>;
}

/**
 * Money as integer micro-units (1/1,000,000 of a currency unit), like x402.
 * Avoids floating point in anything that touches a ceiling or a ledger.
 */
export type Micros = number;

export const MICRO_PER_UNIT = 1_000_000;

export interface Price {
  unitsMicros: number;
  currency: string;
}

export interface Quote extends Price {
  rail: string;
  settlement: 'immediate' | 'batch';
  expiresAt?: string;
}

export function micros(units: number): Micros {
  if (!Number.isFinite(units)) throw new RangeError(`micros(): non-finite unit value ${units}`);
  const v = Math.round(units * MICRO_PER_UNIT);
  if (!Number.isSafeInteger(v)) throw new RangeError(`micros(): precision overflow for ${units}`);
  return v;
}

export function formatMicros(micros_: Micros, currency = 'USD'): string {
  return `${(micros_ / MICRO_PER_UNIT).toFixed(2)} ${currency}`;
}

export function addMicros(a: Micros, b: Micros): Micros {
  if (!Number.isSafeInteger(a) || !Number.isSafeInteger(b)) {
    throw new RangeError('addMicros(): unsafe integer input');
  }
  return a + b;
}

/** Injectable clock + id for deterministic tests and audit replay. */
export interface Clock {
  now(): string;
}

export const systemClock: Clock = {
  now(): string {
    return new Date().toISOString();
  },
};

export const frozenClock = (t = '2026-08-18T00:00:00.000Z'): Clock => ({ now: () => t });

/** Random fetch ids (rfc9562-style ULID would be a drop-in upgrade). */
export function makeFetchId(rand: () => number = Math.random): string {
  const alphabet = '0123456789';
  let id = '';
  for (let i = 0; i < 16; i++) id += alphabet[Math.floor(rand() * 16)]!;
  return `fetch_${id}`;
}

export function makeSettlementRef(rail: string, rand: () => number = Math.random): string {
  let suffix = '';
  for (let i = 0; i < 12; i++) suffix += 'abcdefghijklmnopqrstuvwxyz0123456789'[Math.floor(rand() * 36)]!;
  return `settle_${rail}_${suffix}`;
}

/**
 * Base error hierarchy for the broker.
 * Every error carries a stable `code` so the audit layer and agents can act
 * on failures without parsing messages.
 */
export class BrokerError extends Error {
  public readonly code: string;
  public readonly retryable: boolean;

  constructor(code: string, message: string, options?: { cause?: unknown; retryable?: boolean }) {
    super(message, { cause: options?.cause });
    this.name = new.target.name;
    this.code = code;
    this.retryable = options?.retryable ?? false;
  }
}

/** The request was denied by broker policy or the budget engine before the origin was reached. */
export class BudgetError extends BrokerError {
  constructor(message: string, code: string = 'BUDGET_DENIED', cause?: unknown) {
    super(code, message, { cause });
  }
}

/** A payment rail failed a quote, authorization, or settlement step. */
export class RailError extends BrokerError {
  constructor(message: string, code: string = 'RAIL_ERROR', cause?: unknown, retryable?: boolean) {
    super(code, message, { cause, retryable });
  }
}

/** Identity/attestation failure: missing, expired, or mismatched key. */
export class IdentityError extends BrokerError {
  constructor(message: string, code: string = 'IDENTITY_ERROR', cause?: unknown) {
    super(code, message, { cause });
  }
}

/** License parsing or enforcement failure. */
export class LicenseError extends BrokerError {
  constructor(message: string, code: string = 'LICENSE_ERROR', cause?: unknown) {
    super(code, message, { cause });
  }
}

/** The origin rejected the request outright (403 bot gate, WAF, agent detection). */
export class OriginRejectedError extends BrokerError {
  constructor(message: string, origin: string, httpStatus: number, cause?: unknown) {
    super(
      `ORIGIN_REJECTED`,
      `Origin ${origin} rejected the request with HTTP ${httpStatus}: ${message}`,
      { cause, retryable: true }
    );
  }
}

/** The origin demanded payment (402) and no rail could or should settle it. */
export class PaymentRequiredError extends BrokerError {
  constructor(message: string, code: string = 'PAYMENT_REQUIRED', cause?: unknown) {
    super(code, message, { cause, retryable: true });
  }
}

export function isBrokerError(err: unknown): err is BrokerError {
  return err instanceof BrokerError;
}

/** Deterministic base64url for signatures and payloads. */
export function b64url(bytes: Uint8Array): string {
  return Buffer.from(bytes).toString('base64url');
}

export function fromB64url(s: string): Uint8Array {
  return new Uint8Array(Buffer.from(s, 'base64url'));
}

export function headerRecordToSortedEntries(headers: Record<string, string>): Array<[string, string]> {
  return Object.entries(headers)
    .map(([k, v]) => [k.toLowerCase(), v] as [string, string])
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
}

import { BudgetError, type Clock, type Micros, type Price, type UrlString } from '@mwb/core';
import {
  defaultPolicy,
  matchLineItem,
  type BudgetPolicy,
} from './policy.js';

/**
 * A meter is the accounting state for a tenant's spend.
 *
 * Buckets:
 *  - per-call  : one-shot check, not persistent here.
 *  - hourly    : rolling 1-hour window for the tenant.
 *  - daily     : rolling 24-hour window for the tenant.
 *  - line-item : per-line-item buckets (daily + lifetime).
 *
 * The engine does not persist by itself. `AuditLedger` (or a durable
 * implementation) persists records and rehydrates buckets if needed.
 */
export interface MeterState {
  tenantId: string;
  hourly: { windowStart: number; spentMicros: Micros };
  daily: { windowStart: number; spentMicros: Micros };
  lineItems: Record<string, { dailyMicros: number; lifetimeMicros: number }>;
}

export function emptyMeter(tenantId: string, clock: Clock): MeterState {
  return {
    tenantId,
    hourly: { windowStart: Date.parse(clock.now()), spentMicros: 0 },
    daily: { windowStart: Date.parse(clock.now()), spentMicros: 0 },
    lineItems: {},
  };
}

interface CheckResult {
  ok: boolean;
  code: string;
  reason: string;
  remainingMicros?: number;
}

function checkBucket(
  bucketMicros: number,
  ceilingMicros: number,
  priceMicros: number,
  label: string
): CheckResult {
  const remaining = ceilingMicros - bucketMicros;
  if (remaining < 0) return { ok: false, code: 'CEILING_EXCEEDED', reason: `${label}: already over ceiling` };
  if (priceMicros > remaining) {
    return {
      ok: false,
      code: 'PRICE_EXCEEDS_REMAINING',
      reason: `${label}: requested ${priceMicros} exceeds remaining ${remaining}`,
      remainingMicros: remaining,
    };
  }
  return { ok: true, code: 'OK', reason: '', remainingMicros: remaining };
}

function advanceWindow(
  bucket: { windowStart: number; spentMicros: number },
  nowMs: number,
  windowMs: number
): { windowStart: number; spentMicros: number } {
  if (nowMs - bucket.windowStart >= windowMs) return { windowStart: nowMs, spentMicros: 0 };
  return bucket;
}

const HOUR_MS = 3_600_000;
const DAY_MS = 86_400_000;
/**
 * The Budget Engine.
 *
 * Responsibilities (and only responsibilities):
 *  1. Refuse work that cannot fit inside a declared ceiling.
 *  2. Record work that has been done (paid or denied) into the meter.
 *  3. Tell the caller exactly which ceiling bit and why.
 *
 * It does NOT decide what to pay with, it does NOT sign anything, it
 * does NOT enforce licenses. Those are the Rail Adapter, Identity, and
 * License Engine. Keeping them separate is what makes each one swappable —
 * which is the whole point of "one contract."
 */
export class BudgetEngine {
  private readonly meters = new Map<string, MeterState>();
  private readonly clock: Clock;
  private readonly policy: BudgetPolicy;

  constructor(options?: { clock?: Clock; policy?: BudgetPolicy }) {
    this.clock = options?.clock ?? { now: () => new Date().toISOString() };
    this.policy = options?.policy ?? defaultPolicy;
  }

  get policy(): BudgetPolicy {
    return this.policy;
  }

  /**
   * Pre-flight: will this request fit?
   *
   * This is the ONLY pre-payment step that may raise BudgetError. The
   * broker surfaces it as `failureClass: 'blocked'` — a policy denial —
   * which the audit layer records as a `denied` row.
   *
   * Deliberately throws (not returns a decision object) because "does not
   * fit" is an exceptional condition for the caller and the audit trail
   * cares about the message, not a tagged union.
   */
  preflight(tenantId: string, price: Price, url?: UrlString): void {
    if (price.currency !== this.policy.currency) {
      throw new BudgetError(
        `Tenant currency mismatch: policy is ${this.policy.currency}, quote is ${price.currency}`,
        'CURRENCY_MISMATCH'
      );
    }
    if (!Number.isSafeInteger(price.unitsMicros) || price.unitsMicros <= 0) {
      throw new BudgetError(`Quote must be a positive safe integer, got ${price.unitsMicros}`, 'BAD_QUOTE');
    }
    if (price.unitsMicros > this.policy.perCallCeilingMicros) {
      throw new BudgetError(
        `Per-call ceiling exceeded: quote ${price.unitsMicros} > ${this.policy.perCallCeilingMicros}`,
        'PER_CALL_CEILING'
      );
    }

    const nowMs = Date.parse(this.clock.now());
    const state = this.getOrCreate(tenantId, nowMs);

    state.hourly = advanceWindow(state.hourly, nowMs, HOUR_MS);
    state.daily = advanceWindow(state.daily, nowMs, DAY_MS);

    const hourlyCheck = checkBucket(
      state.hourly.spentMicros,
      this.policy.hourlyTenantCeilingMicros,
      price.unitsMicros,
      `hourly tenant ceiling`
    );
    if (!hourlyCheck.ok) throw new BudgetError(hourlyCheck.reason, hourlyCheck.code);

    const dailyCheck = checkBucket(
      state.daily.spentMicros,
      this.policy.dailyTenantCeilingMicros,
      price.unitsMicros,
      `daily tenant ceiling`
    );
    if (!dailyCheck.ok) throw new BudgetError(dailyCheck.reason, dailyCheck.code);

    if (url) {
      const li = matchLineItem(this.policy, url);
      if (li) {
        if (price.currency !== li.currency) {
          throw new BudgetError(
            `Line-item currency mismatch: ${li.currency} vs quote ${price.currency}`,
            'LINE_ITEM_CURRENCY'
          );
        }
        const bucket = state.lineItems[li.match] ?? { dailyMicros: 0, lifetimeMicros: 0 };
        const dCheck = checkBucket(
          bucket.dailyMicros,
          li.dailyCeilingMicros,
          price.unitsMicros,
          `line-item daily (${li.match})`
        );
        if (!dCheck.ok) throw new BudgetError(dCheck.reason, dCheck.code);
        const lCheck = checkBucket(
          bucket.lifetimeMicros,
          li.lifetimeCeilingMicros,
          price.unitsMicros,
          `line-item lifetime (${li.match})`
        );
        if (!lCheck.ok) throw new BudgetError(lCheck.reason, lCheck.code);
      }
    }
  }

  /**
   * Record a completed paid fetch. Advances every meter that was charged
   * for this call. The broker calls this exactly once per settled fetch.
   */
  recordPaid(tenantId: string, price: Price, url: UrlString): void {
    const nowMs = Date.parse(this.clock.now());
    const state = this.getOrCreate(tenantId, nowMs);
    state.hourly = advanceWindow(state.hourly, nowMs, HOUR_MS);
    state.daily = advanceWindow(state.daily, nowMs, DAY_MS);
    state.hourly.spentMicros += price.unitsMicros;
    state.daily.spentMicros += price.unitsMicros;

    const li = matchLineItem(this.policy, url);
    if (li) {
      const bucket = state.lineItems[li.match] ?? { dailyMicros: 0, lifetimeMicros: 0 };
      bucket.dailyMicros += price.unitsMicros;
      bucket.lifetimeMicros += price.unitsMicros;
      state.lineItems[li.match] = bucket;
    }
  }

  /**
   * Record a denied fetch. Does NOT charge, but SHOULD be observed on
   * dashboards to distinguish "the agent tried and was stopped by us" from
   * "the agent tried and was stopped by the origin."
   *
   * Denial rows live in the audit ledger; this hook is kept so a future
   * in-memory rate limiter (e.g. deny-burst) can subscribe uniformly.
   */
  recordDenied(_tenantId: string): void {
    // Intentionally no-op in-memory; the audit ledger is the source of truth.
  }

  /** Snapshot of current meter state for the dashboard. */
  snapshot(tenantId: string): MeterState {
    const state = this.meters.get(tenantId);
    if (!state) throw new BudgetError(`Unknown tenant: ${tenantId}`, 'UNKNOWN_TENANT');
    return structuredClone(state);
  }

  private getOrCreate(tenantId: string, nowMs: number): MeterState {
    let state = this.meters.get(tenantId);
    if (!state) {
      state = emptyMeter(tenantId, { now: () => new Date(nowMs).toISOString() });
      this.meters.set(tenantId, state);
    }
    return state;
  }
}

// Re-export so imports don't need to reach into the policy module.
export { defaultPolicy, matchLineItem, globMatch } from './policy.js';
export type { BudgetPolicy, LineItem } from './policy.js';

import type { FailureClass, Price, UrlString } from '@mwb/core';

/**
 * Budget decision returned by the BudgetEngine before the broker does any
 * network work, or after it observes the origin's response.
 *
 * The point: a "generic failure" is no longer reportable. Every terminal
 * state maps to one of the three classes so an agent (or a human dashboard)
 * can say exactly why the cost decision happened.
 */
export type PreFlightDecision =
  | {
      kind: 'allow';
      /** The price quote the engine will pay without further action. */
      quote: Price;
      /** Rail the quote came from; the broker pays through this rail. */
      rail: string;
      note?: string;
    }
  | {
      kind: 'require-settlement';
      /** Quote that needs an explicit settlement authorization. */
      quote: Price;
      rail: string;
      reason: string;
    }
  | {
      kind: 'deny';
      failureClass: Extract<FailureClass, 'blocked' | 'token-rejected'>;
      code: string;
      reason: string;
    };

export type OutcomeDecision =
  | { kind: 'record-paid'; failureClass?: never }
  | { kind: 'record-denied'; failureClass: FailureClass; code?: string; reason: string };

/**
 * A line-item: the recurring ceiling that groups URLs (e.g. all fetches to
 * news-site.com, or a domain group). Treated like a monthly credit line.
 */
export interface LineItem {
  /** Glob over host + path. Supports `*` anywhere. */
  match: string;
  /** Max spend per calendar day, in micros. */
  dailyCeilingMicros: number;
  /** Hard cap over the line item's lifetime, in micros. */
  lifetimeCeilingMicros: number;
  currency: string;
  label?: string;
}

/**
 * Tenant-level policy. All ceilings are in micros (1/1,000,000 of a unit).
 * Defaults are chosen to be strict enough to be useful and loose enough
 * not to block a demo: one fetch must always fit inside every ceiling.
 */
export interface BudgetPolicy {
  /** Absolute cap per fetch, in micros. Default 10_000 (0.01). */
  perCallCeilingMicros: number;
  /** Cap per tenant per rolling hour, in micros. Default 100_000 (0.10). */
  hourlyTenantCeilingMicros: number;
  /** Cap per tenant per rolling day, in micros. Default 1_000_000 (1.00). */
  dailyTenantCeilingMicros: number;
  currency: string;
  /** Line items are consulted after the per-call check; a fetch can fit
   * the per-call rule but still exceed the line-item rule. */
  lineItems: LineItem[];
}

export const defaultPolicy: BudgetPolicy = Object.freeze({
  perCallCeilingMicros: 10_000,
  hourlyTenantCeilingMicros: 100_000,
  dailyTenantCeilingMicros: 1_000_000,
  currency: 'USD',
  lineItems: [],
});

export function matchLineItem(policy: BudgetPolicy, url: UrlString): LineItem | undefined {
  const u = new URL(url);
  const haystack = u.host + u.pathname;
  return policy.lineItems.find((li) => globMatch(li.match, haystack) ?? false);
}

/** A very small glob: `*` matches any run of chars. Sufficient for the
 *  line-item matcher; not a general-purpose path matcher on purpose. */
export function globMatch(pattern: string, haystack: string): boolean {
  const re = new RegExp(
    '^' +
      pattern
        .split('*')
        .map((part) => part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))
        .join('.*') +
      '$'
  );
  return re.test(haystack);
}

export {
  BudgetEngine,
  defaultPolicy,
  matchLineItem,
  globMatch,
} from './engine.js';
export type { BudgetPolicy, LineItem } from './policy.js';
export { emptyMeter } from './engine.js';
export type { MeterState } from './engine.js';

import type {
  Clock,
  FetchOutcome,
  FailureClass,
  LedgerEntry,
} from '@mwb/core';

/**
 * The ledger is the broker's source of truth: every fetch the broker
 * attempted — fulfilled, denied, failed — appears exactly once.
 *
 * `seq` is monotonically increasing and gap-free; that invariant is what the
 * reconciliation step verifies. If the broker crashes or an origin
 * settlement is missing, reconciliation surfaces it instead of hiding it.
 */
export class AuditLedger {
  readonly entries: LedgerEntry[] = [];
  private seq = 0;
  private readonly clock: Clock;

  constructor(options?: { clock?: Clock }) {
    this.clock = options?.clock ?? { now: () => new Date().toISOString() };
  }

  /** Append one row for one fetch attempt. Idempotent per fetchId. */
  record(outcome: FetchOutcome, options?: { tenantId?: string }): LedgerEntry {
    const existing = this.entries.find((e) => e.fetchId === outcome.fetchId);
    if (existing) return existing;

    this.seq += 1;
    const now = this.clock.now();
    const row: LedgerEntry = {
      seq: this.seq,
      fetchId: outcome.fetchId,
      tenantId: options?.tenantId ?? outcome.tenantId ?? 'default',
      url: outcome.origin?.url ?? 'unknown',
      status: outcome.status === 'fulfilled' ? 'fulfilled' : 'denied',
      failureClass: outcome.failureClass,
      httpStatus: outcome.origin?.httpStatus,
      priceMicros: outcome.price?.unitsMicros,
      currency: outcome.price?.currency,
      rail: outcome.rail,
      licenseId: outcome.license?.id,
      keyId: outcome.identity?.keyId,
      settlementRef: outcome.settlementRef,
      startedAt: outcome.timestamps.startedAt,
      completedAt: outcome.timestamps.completedAt,
      recordedAt: now,
    };
    this.entries.push(row);
    return row;
  }

  /** Gap-free, monotonically increasing seq. */
  lastSeq(): number {
    return this.seq;
  }

  byTenant(tenantId: string): LedgerEntry[] {
    return this.entries.filter((e) => e.tenantId === tenantId);
  }

  byUrl(url: string): LedgerEntry[] {
    return this.entries.filter((e) => e.url === url);
  }

  toRows(): LedgerEntry[] {
    return this.entries.map((e) => structuredClone(e));
  }
}

export interface LedgerSummary {
  total: number;
  fulfilled: number;
  denied: number;
  byFailureClass: Record<string, number>;
  spendMicros: number;
  byRail: Record<string, number>;
  byLicense: Record<string, number>;
}

export function summarize(rows: LedgerEntry[]): LedgerSummary {
  const s: LedgerSummary = {
    total: rows.length,
    fulfilled: 0,
    denied: 0,
    byFailureClass: {},
    spendMicros: 0,
    byRail: {},
    byLicense: {},
  };
  for (const r of rows) {
    if (r.status === 'fulfilled') s.fulfilled += 1;
    else s.denied += 1;
    if (r.failureClass) s.byFailureClass[r.failureClass] = (s.byFailureClass[r.failureClass] ?? 0) + 1;
    if (r.status === 'fulfilled' && r.priceMicros != null) s.spendMicros += r.priceMicros;
    if (r.rail) s.byRail[r.rail] = (s.byRail[r.rail] ?? 0) + 1;
    if (r.licenseId) s.byLicense[r.licenseId] = (s.byLicense[r.licenseId] ?? 0) + 1;
  }
  return s;
}

export interface ReconciliationReport {
  ok: boolean;
  problems: string[];
  checks: {
    seqGapFree: boolean;
    deniedHasFailureClass: boolean;
    fulfilledHasSettlement: boolean;
    fulfilledHasPrice: boolean;
  };
}

/**
 * Reconcile the ledger against invariants:
 *  - seq is gap-free starting at 1
 *  - every denied row has a failureClass (the three-classes invariant)
 *  - every fulfilled row has a settlementRef (we paid, we can prove it)
 *  - every fulfilled row has a price (we can bill what we paid)
 */
export function reconcile(rows: LedgerEntry[]): ReconciliationReport {
  const problems: string[] = [];

  const seqGapFree =
    rows.length === 0 ||
    rows.every((r, i) => r.seq === i + 1);

  const deniedHaveFC = rows
    .filter((r) => r.status !== 'fulfilled')
    .every((r) => r.failureClass !== undefined);

  const fulfilledHasSett = rows
    .filter((r) => r.status === 'fulfilled')
    .every((r) => (r.settlementRef ?? '').length > 0);

  const fulfilledHasPrice = rows
    .filter((r) => r.status === 'fulfilled')
    .every((r) => r.priceMicros != null && r.priceMicros > 0);

  if (!seqGapFree) problems.push('seq is not gap-free starting at 1');
  if (!deniedHaveFC) problems.push('a denied row lacks a failureClass');
  if (!fulfilledHasSett)
    problems.push('a fulfilled row lacks a settlementRef (settlement not proven)');
  if (!fulfilledHasPrice) problems.push('a fulfilled row lacks a positive price');

  return {
    ok:
      seqGapFree && deniedHaveFC && fulfilledHasSett && fulfilledHasPrice,
    problems,
    checks: { seqGapFree, deniedHasFailureClass: deniedHaveFC, fulfilledHasSettlement: fulfilledHasSett, fulfilledHasPrice },
  };
}

