describe('Broker.fetch — idempotency', () => {
  it('returns the cached outcome and only charges/re-rows once', async () => {
    const { ledger, budget, rail } = make();
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin()) } });
    const f = makeFetchId();

    const a = await broker.fetch({ url: URL, fetchId: f });
    const b = await broker.fetch({ url: URL, fetchId: f });

    expect(broker.rowFor(f)).toBe(ledger.entries[0]);
    expect(ledger.entries.length).toBe(1);
    expect(a.fetchId).toBe(b.fetchId);
    expect(a.status).toBe(b.status);
  });
});

describe('Broker.fetch — terminal-class invariant', () => {
  it('every denied path is one of the three failure classes and reconciles', async () => {
    const valid: TerminalKind[] = ['fulfilled', 'blocked', 'payment-required', 'token-rejected'];

    const makeBroker = (cfg: {
      origin?: OriginResponse;
      failureMode?: 'none' | 'quote' | 'authorize' | 'settle';
      currency?: string;
      ceiling?: number;
      ring?: boolean;
    } = {}) => {
      const budget = new BudgetEngine({
        policy: { ...defaultPolicy, ...(cfg.ceiling != null ? { perCallCeilingMicros: cfg.ceiling } : {}) },
        clock,
      });
      const ledger = new AuditLedger({ clock });
      const rail = new InMemoryRail({
        id: 'x402',
        priceMicros: cfg.ceiling != null ? cfg.ceiling + 5000 : PRICE,
        currency: cfg.currency,
        clock,
        failureMode: cfg.failureMode,
      });
      const broker = new Broker({
        rail, budget, ledger,
        ...(cfg.ring ? { ring: new KeyRing(clock) } : {}),
        origin: { fetch: () => Promise.resolve(cfg.origin ?? origin()) },
      });
      return { broker, ledger };
    };

    const configs = [
      makeBroker({ ceiling: 100 }),
      makeBroker({ currency: 'EUR' }),
      makeBroker({ failureMode: 'authorize' }),
      makeBroker({ failureMode: 'settle' }),
      makeBroker({ origin: origin({ httpStatus: 402 }) }),
      makeBroker({ origin: origin({ httpStatus: 403 }), ring: true }),
      makeBroker({ origin: origin({ httpStatus: 403 }) }),
      makeBroker(),
    ];

    for (const { broker, ledger } of configs) {
      const o = await broker.fetch({ url: URL });
      expect(valid).toContain(o.failureClass ?? 'fulfilled');
      if (o.status === 'denied') expect(o.failureClass).toBeDefined();
      const rep = reconcile(ledger.entries);
      expect(rep.ok).toBe(true);
      expect(rep.problems).toEqual([]);
    }
  });
});

import { LicenseError } from '@mwb/core';
import type { License, LicenseObligation, RslClause } from '@mwb/core';

/**
 * License Engine — the broker's compliance layer.
 *
 * Three jobs, all read-only with respect to the network:
 *   1. `parseLicense`     — turn a raw RSL source (a parsed body or a
 *      `Link` header) into a typed `License`.
 *   2. `deriveObligations` — read those terms and produce the concrete,
 *      fetch-scoped obligations the caller must satisfy (attribution,
 *      no-store, pay-per-inference budget, …).
 *   3. `enforce` / `resolveStoreability` — post-fetch checks: did the
 *      caller's actions violate a term?
 *
 * RSL (Really Simple Licensing) terms ride in an HTTP `Link` header, e.g.
 *
 *     Link: <https://licenses.example/r/73>; rel="type:license-terms"
 *
 * with a JSON body that carries the `terms` array. This module builds
 * against that *pattern*; draft field names may drift, so parsing is
 * defensive. Draft-caveat discipline: parse against the shape above, never
 * a draft's exact wire grammar.
 */

/** A clause, as it appears in an RSL `terms` array. */
export interface RslTermInput {
  type: string;
  value?: boolean | number | string;
  params?: Record<string, string | number>;
}

/** A parsed RSL body, matching the accepted JSON shape. */
export interface RslBodyLike {
  draft?: string;
  id?: string;
  title?: string;
  publishedAt?: string;
  terms?: RslTermInput[];
}

export interface LicenseParseOptions {
  /** A `Link` header (or just its URL) identifying the terms document. */
  link?: string;
  /**
   * The raw source string, preserved verbatim on the parsed License for the
   * audit trail. Defaults to whatever was parsed if it was a string.
   */
  rawSource?: string;
}

/**
 * Parse an RSL source into a License.
 *
 * Accepts:
 *  - a JSON string with a `terms` array (or an `RslBodyLike` object)
 *  - a `Link` header string such as
 *    `<https://licenses.example/r/73>; rel="type:license-terms"`
 *  - `options.link` to attach a terms id when the body carries no `id`.
 */
export function parseLicense(
  source: string | RslBodyLike,
  options: LicenseParseOptions = {}
): License {
  let body: RslBodyLike = { ...(source && typeof source === 'object' ? source : {}) };
  let rawSource: string | undefined = options.rawSource;

  if (typeof source === 'string') {
    const s = source.trim();
    if (s.startsWith('{')) {
      try {
        body = { ...(JSON.parse(s) as RslBodyLike) };
      } catch (cause) {
        throw new LicenseError(`RSL body is not valid JSON: ${s}`, 'RSL_PARSE', cause);
      }
      rawSource ??= source;
    } else {
      // It is a Link header (or bare URL) identifying the terms doc.
      const link = extractLink(s);
      body.id = body.id ?? link.id;
      body.draft = body.draft ?? link.draft;
      rawSource ??= source;
    }
  }

  const id = body.id?.trim() || linkId(body.link as string | undefined);
  if (!id) {
    throw new LicenseError('RSL source carried no license identifier', 'RSL_NO_ID');
  }

  return {
    draft: body.draft?.trim() || 'urn:rsl:draft:unregistered',
    id,
    title: body.title,
    publishedAt: body.publishedAt,
    clauses: normalizeClauses(body.terms),
    rawSource: rawSource ?? body.rawSource ?? `<${id}>`,
  };
}

/**
 * Derive the fetch-scoped obligations from a license. An empty terms array
 * yields no obligations; the broker still surfaces the `License` so the
 * caller can see what it is (not) bound to.
 */
export function deriveObligations(license: License): LicenseObligation[] {
  const out: LicenseObligation[] = [];
  for (const clause of license.clauses) {
    const { instruction, kind } = clauseToObligation(clause.type, clause.params);
    if (instruction) out.push({ clause: clause.type, kind, instruction });
  }
  return out;
}

/**
 * Whether the broker may mark the fetched content storeable given the
 * license. A `no-store` marked `forbidden` makes it non-storeable; anything
 * else leaves storeability to the caller.
 */
export function resolveStoreability(license: License): boolean {
  return !license.clauses.some((c) => c.type === 'no-store' && c.value === 'forbidden');
}

/** Post-fetch actions the caller may have taken. */
export interface EnforcementActions {
  /** Did the caller store/cache the content? */
  store?: boolean;
  /** Attribution notice included when storing, if any (non-empty ⇒ provided). */
  attribution?: string;
  /** Is the usage commercial? */
  commercialUse?: boolean;
  /** Did the caller produce a derivative work from stored content? */
  derived?: boolean;
  /** Number of model inferences run, if any. */
  inferenceCount?: number;
}

export interface EnforcementResult {
  pass: boolean;
  violations: string[];
  obligations: LicenseObligation[];
}

/**
 * Check the caller's post-fetch actions against the license. Returns the
 * derived obligations plus any violations — the broker surfaces this so a
 * call that "worked" can still report a compliance problem.
 *
 * Pay-per-inference is advisory (a budget, not a hard gate): the settlement
 * row is the proof of payment, so the engine never blocks on it.
 */
export function enforce(
  license: License,
  actions: EnforcementActions = {}
): EnforcementResult {
  const violations: string[] = [];

  for (const clause of license.clauses) {
    if (clause.type === 'no-store' && clause.value === 'forbidden' && actions.store) {
      violations.push('no-store: content must not be stored, but store was requested');
    }
    if (clause.type === 'no-commercial-use' && clause.value === 'forbidden' && actions.commercialUse) {
      violations.push('no-commercial-use: usage is commercial, which the license forbids');
    }
    if (
      clause.type === 'no-derivative-works' &&
      clause.value === 'forbidden' &&
      actions.store &&
      actions.derived
    ) {
      violations.push('no-derivative-works: content was stored and transformed');
    }
  }

  const wantsAttribution = license.clauses.some((c) => c.type === 'attribution' && c.value === 'required');
  if (wantsAttribution && actions.store && !attributionProvided(actions)) {
    violations.push('attribution: content was stored without the required attribution notice');
  }

  return { pass: violations.length === 0, violations, obligations: deriveObligations(license) };
}

function attributionProvided(actions: EnforcementActions): boolean {
  return typeof actions.attribution === 'string' && actions.attribution.length > 0;
}

// --- clause mapping -------------------------------------------------------

/** Translate a single clause to the obligation it imposes, if any. */
function clauseToObligation(
  type: string,
  params?: Record<string, string | number>
): { instruction?: string; kind: LicenseObligation['kind'] } {
  switch (type) {
    case 'attribution':
      if (params?.by) return { kind: 'notice', instruction: `Include attribution to ${params.by} when using this content.` };
      return { kind: 'notice', instruction: 'Include attribution when using this content.' };
    case 'no-store':
      return { kind: 'store-prohibited', instruction: 'Do not store or cache this content.' };
    case 'no-derivative-works':
      return { kind: 'forbidden', instruction: 'Do not create derivative works from this content.' };
    case 'no-commercial-use':
      return { kind: 'forbidden', instruction: 'Commercial use of this content is forbidden.' };
    case 'redistribution':
      return { kind: 'forbidden', instruction: 'Redistribution of this content is forbidden.' };
    default:
      return { kind: 'notice', instruction: `License term ${type} applies; review its conditions.` };
  }
}

// --- helpers --------------------------------------------------------------

/** RSL treats a bare clause as required; the engine is predictable about it. */
function normalizeClauses(terms?: RslTermInput[]): RslClause[] {
  if (!terms) return [];
  const out: RslClause[] = [];
  for (const t of terms) {
    if (!t || typeof t.type !== 'string' || !t.type) {
      throw new LicenseError(`RSL clause is missing a type: ${JSON.stringify(t)}`, 'RSL_BAD_CLAUSE');
    }
    out.push({
      type: t.type,
      value: t.value ?? 'required',
      params: t.params ?? {},
    });
  }
  return out;
}

/** Parse a `Link` header (or bare URL) into { id, draft }. */
function extractLink(link: string): { id: string; draft?: string } {
  const url = linkUrl(link);
  if (!url) return { id: '' };
  return { id: slugFromUrl(url), draft: draftFromUrl(url) };
}

/** A `Link: <url>; rel="..."` or a bare `<url>` / url → the URL string. */
function linkUrl(link: string): string {
  const brace = link.match(/<([^>]*)>/);
  if (brace) return brace[1]!;
  const token = (link.trim().split(/\s|;/)[0] ?? '').trim();
  return token.startsWith('http') ? token : '';
}

/** https://h.example.com/r/73 → https://h.example.com/r/73. */
function slugFromUrl(url: string): string {
  try {
    return new URL(url).href;
  } catch {
    return url;
  }
}

/** A draft label is best-effort; used only if the body carried no draft. */
function draftFromUrl(url: string): string | undefined {
  try {
    return new URL(url).hostname || undefined;
  } catch {
    return undefined;
  }
}

/** Alias used by the top-level parse path for a link given via options. */
function linkId(link?: string): string {
  if (!link) return '';
  return extractLink(link.trim()).id;
}

